CREATE OR REPLACE FUNCTION public.can_manage_user_access() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT coalesce(auth.uid() IN ('d58f0c77-e079-4c01-aba5-b3dda75d8071'::uuid, 'a6df6d4c-87c9-4349-b1af-0f55e2dc4bfd'::uuid) AND public.has_role(auth.uid(), 'admin') AND EXISTS (SELECT 1 FROM public.profiles WHERE id = auth.uid() AND active), false) $$;